"""Public aggregate-only report. Separate asset/gap populations; no edge selection."""
import argparse,json,csv,math,statistics,hashlib
from pathlib import Path

def write_csv(path,rows):
 if rows:
  with path.open('w') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
def analyze(inputs,roster,out):
 out.mkdir(parents=True,exist_ok=True);configs=roster['configs'];names=['AVZ25 denso','AVZ25 referencia','AVZ200 densidad','BT2 denso','BT2 referencia','BT2 200','Abs denso','Abs referencia','Abs 50'];labels={c['config_sha256']:names[i] for i,c in enumerate(configs)};summary={};pairs=[];sessions=[];cuts=[]
 for path in inputs:
  r=json.loads(path.read_bytes());a=r['asset'];ev=r['evaluation_sessions'];n=sum(s['common_usable_anchors'] for s in ev);gap=r.get('observation_max_gap_ns',2000000000)
  assert len(ev)>=6 and len(r['pairs'])==18 and len(r['training_sessions'])==6 and r['raw_exported'] is False and r['holdout_opened'] is False
  for model in ('CONTINUOUS','PRIOR'):assert math.isclose(statistics.mean(s['baseline_mean_brier'][model] for s in ev),r['baseline_mean_session_brier'][model],abs_tol=1e-12)
  counts={model:0 for model in ('DENSITY','GEOMETRY','ARRIVAL','INTERACTION')};cc={'GEOMETRY':0,'ARRIVAL':0,'INTERACTION':0};full_ds=[];supported=joint_supported=favorable=0
  for j,p in enumerate(r['pairs']):
   name=labels[p['left_config_sha256']]+' × '+labels[p['right_config_sha256']];scores=p['mean_session_brier'];deltas={model:scores[model]-scores['CONTINUOUS'] for model in counts};row={'asset':a,'max_observed_gap_seconds':gap/1e9,'pair':name,'pair_sha256':p['pair_sha256'],'evaluation_sessions':len(ev),'common_anchors':n,'baseline_brier':scores['CONTINUOUS'],**{m+'_minus_base':v for m,v in deltas.items()}}
   for m,v in deltas.items():counts[m]+=int(v<0)
   for m in cc:
    d=scores[m]-scores[m+'_CC'];assert math.isclose(d,p['paired_delta_equal_session_mean'][m+'_MINUS_'+m+'_CC'],abs_tol=1e-12);row[m+'_minus_capacity_control']=d;cc[m]+=int(d<0)
   row['full_minus_mirror']=scores['INTERACTION']-scores['MIRROR_FULL'];row['inside_both']=sum(s['crossfamily_context']['pair_counts'][j]['inside_both'] for s in ev);row['both_present']=sum(s['crossfamily_context']['pair_counts'][j]['both_present'] for s in ev)
   for m in ('CONTINUOUS','DENSITY','GEOMETRY','ARRIVAL','INTERACTION'):
    independent=statistics.mean(s['pairs'][j]['scores']['mean_brier'][m] for s in ev);assert math.isclose(independent,scores[m],abs_tol=1e-12)
   full_ds.append(deltas['INTERACTION']);pairs.append(row)
   for s in ev:
    z=s['pairs'][j];assert z['scores']['anchors']==s['common_usable_anchors'];sessions.append({'asset':a,'max_observed_gap_seconds':gap/1e9,'trade_date':s['trade_date'],'pair':name,'pair_sha256':p['pair_sha256'],'anchors':z['scores']['anchors'],**z['scores']['mean_brier'],**z['paired_deltas']})
   for key,g in r['arrival_context_summaries'][j].items():
    nn=g['anchors'];d=g['loss_sums']['ARRIVAL']/nn-g['loss_sums']['CONTINUOUS']/nn;dc=g['loss_sums']['ARRIVAL']/nn-g['loss_sums']['ARRIVAL_CC']/nn;passed=g['support_screen_passed_not_edge'];assert passed==(nn>=2000 and g['support_sessions']>=6)
    supported+=int(passed);joint_supported+=int(passed and key.startswith('INSIDE_BOTH'));favorable+=int(passed and d<0 and dc<0);cuts.append({'asset':a,'max_observed_gap_seconds':gap/1e9,'pair':name,'scenario':key,'anchors':nn,'support_sessions':g['support_sessions'],'arrival_improved_sessions':g['arrival_improved_sessions'],'support_screen_passed_not_edge':passed,'arrival_minus_base_pooled':d,'arrival_minus_control_pooled':dc})
  cache=r['shared_footprint_cache'];births=[sum(s['native_scene']['config_counts'][j].get('BIRTH',0) for s in ev) for j in range(9)]
  summary[a]={'plan_sha256':r['plan_sha256'],'receipt_sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'max_observed_gap_seconds':gap/1e9,'evaluation_sessions':len(ev),'evaluation_dates':[s['trade_date'] for s in ev],'unavailable_sessions':r['unavailable_evaluation_sessions'],'common_anchors':n,'baseline_brier':r['baseline_mean_session_brier']['CONTINUOUS'],'pairs_below_base':counts,'pairs_below_capacity_control':cc,'full_minus_base_range':{'min':min(full_ds),'max':max(full_ds)},'full_improved_sessions_by_pair':[sum(s['pairs'][j]['scores']['mean_brier']['INTERACTION']<s['baseline_mean_brier']['CONTINUOUS'] for s in ev) for j in range(18)],'supported_arrival_cuts_not_edge':supported,'supported_joint_arrival_cuts_not_edge':joint_supported,'supported_arrival_cuts_below_both_base_and_control_not_edge':favorable,'native_births_by_config':dict(zip(names,births)),'inside_both_by_pair':[z['inside_both'] for z in pairs if z['asset']==a],'runner_seconds':r['wall_seconds'],'native_stage_seconds':r['native_stage_seconds'],'bt2a_runner_fraction':r['native_stage_seconds']['BT2A']/r['wall_seconds'],'cache_hit_fraction':cache['hits']/(cache['hits']+cache['misses']),'cache_receipt':cache,'runner_peak_rss_bytes':r['measured_runner_peak_rss_bytes'],'measured_speedup_vs_uncached_market_baseline':None}
 evidence={'schema':'multiasset_crossfamily_analysis_v1','grain':'own asset and observed-gap protocol x session x pair; pairs/anchors not independent','equal_session_headline_weights':True,'pooled_anchor_weights_only_for_predefined_scenario_cuts':True,'cross_asset_mean_computed':False,'models_per_asset':146,'pairs_per_asset':18,'approximate_NT8_parity_accepted_not_100pct_measured':True,'assets':summary,'visual_plan':[{'comparison':'count of18pair means below own baseline or own capacity control','grain':'asset and gap protocol','population':'all18pairs per complete asset','unit':'pair count','disposition':'chart','reason':'distinguishes full model failure from limited representation improvements; protocols must be visibly distinct'},{'comparison':'all pair effect sizes and supported/unsupported17arrival cuts','grain':'asset x pair and overlapping scenario','disposition':'table','reason':'lookup detail and rare coincidence support, no survivor-only shortlist'},{'comparison':'cache and native runtime stage','grain':'single perasset run','disposition':'prose','reason':'no uncached samepopulation runtime comparator, cannot claim market speedup'}],'canonical_brain_written':False,'edge_claim':False}
 (out/'analysis.json').write_text(json.dumps(evidence,indent=2)+'\n');write_csv(out/'pairs.csv',pairs);write_csv(out/'session_pairs.csv',sessions);write_csv(out/'arrival_cuts.csv',cuts);return evidence
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--receipt',action='append',required=True);p.add_argument('--roster',required=True);p.add_argument('--out',required=True);a=p.parse_args();r=analyze([Path(x) for x in a.receipt],json.loads(Path(a.roster).read_bytes()),Path(a.out));print(json.dumps({'assets':{k:{z:v[z] for z in ('evaluation_sessions','common_anchors','pairs_below_base','pairs_below_capacity_control','supported_joint_arrival_cuts_not_edge')} for k,v in r['assets'].items()}},indent=2))
